        // Interpolate the local artwork correction along the nearest known road.
        // Uncalibrated roads retain their original projection. Fade at the edge
        // rather than pulling an unrelated custom route onto a different road.
        internal static Vector3 Correct(Vector3 point)
        {
            Vector2 p = new Vector2(point.x, point.z);
            float best = 30f * 30f;
            Vector2 correction = Vector2.zero;
            for (int r = 0; r < Roads.Length; r++)
            {
                float[] road = Roads[r];
                for (int i = 0; i + 7 < road.Length; i += 4)
                {
                    Vector2 a = new Vector2(road[i], road[i + 1]);
                    Vector2 b = new Vector2(road[i + 4], road[i + 5]);
                    Vector2 ab = b - a;
                    float t = ab.sqrMagnitude < 0.001f ? 0f
                        : Mathf.Clamp01(Vector2.Dot(p - a, ab) / ab.sqrMagnitude);
                    float distance = (p - (a + ab * t)).sqrMagnitude;
                    if (distance >= best) continue;
                    best = distance;
                    correction = Vector2.Lerp(
                        new Vector2(road[i + 2], road[i + 3]),
                        new Vector2(road[i + 6], road[i + 7]), t);
                }
            }
            float weight = Mathf.Clamp01((30f - Mathf.Sqrt(best)) / 20f);
            return new Vector3(point.x + correction.x * weight, point.y,
                               point.z + correction.y * weight);
        }
    }
